    function insertCategoriesWithRelation(array $categories, Category $parent = null)
    {
        foreach ($categories as $categoryData) {
            $children = $categoryData['children'] ?? [];
            unset($categoryData['children']);

            if ($parent) {
                $category = $parent->children()->create($categoryData);
            } else {
                $category = Category::create($categoryData);
            }

            if (!empty($children)) {
                $this->insertCategoriesWithRelation($children, $category);
            }
        }
    }
